# -*- coding: utf-8 -*-
"""
Language & Humanities Flashcards Generator (English, Citizenship, IT)
Grades 9, 10, 11, 12
"""

def generate_language_humanities(add):
    # =========================================================================
    # 📖 ENGLISH LANGUAGE & GRAMMAR (GRADES 9-12)
    # =========================================================================
    # Grade 9 English
    add(9, "english", 1, "State the structure and usage of the Zero Conditional.", "Structure: If + Present Simple, Present Simple.\nUsage: Scientific facts, universal laws, and general truths.\nExample: If you heat ice, it melts.", "formula")
    add(9, "english", 1, "State the structure and usage of the First Conditional.", "Structure: If + Present Simple, will + Base Verb.\nUsage: Real or very likely future possibilities.\nExample: If it rains tomorrow, we will stay home.", "formula")
    add(9, "english", 2, "State the structure and usage of the Second Conditional.", "Structure: If + Past Simple, would + Base Verb.\nUsage: Hypothetical, unreal, or imaginary present/future situations.\nExample: If I had a million dollars, I would travel the world.", "formula")
    add(9, "english", 2, "State the structure and usage of the Third Conditional.", "Structure: If + Past Perfect, would have + Past Participle.\nUsage: Unreal past events, expressing regrets or impossible past conditions.\nExample: If she had studied harder, she would have passed the matric exam.", "formula")
    add(9, "english", 3, "What is the Passive Voice transformation rule for the Present Simple?", "Active: Subject + Verb(s) + Object.\nPassive: Object + is/am/are + Past Participle (V3) + (by Subject).\nExample: 'He writes the report' -> 'The report is written by him'.", "formula")
    add(9, "english", 3, "What is the Passive Voice transformation rule for the Past Simple?", "Active: Subject + V2 + Object.\nPassive: Object + was/were + Past Participle (V3) + (by Subject).\nExample: 'The workers built the bridge' -> 'The bridge was built by the workers'.", "formula")
    add(9, "english", 4, "What tense changes occur when converting Direct Speech to Reported Speech?", "Present Simple -> Past Simple\nPresent Continuous -> Past Continuous\nPresent Perfect -> Past Perfect\nPast Simple -> Past Perfect\nwill -> would, can -> could, may -> might.", "concept")
    add(9, "english", 4, "How do time expressions change in Reported Speech?", "today -> that day\nyesterday -> the day before / the previous day\ntomorrow -> the next day / the following day\nnow -> then\nhere -> there\nthis -> that.", "definition")
    add(9, "english", 5, "State the Subject-Verb Agreement rule for 'Either...or' and 'Neither...nor'.", "When two subjects are joined by 'either...or' or 'neither...nor', the verb agrees in number and person with the nearer subject.\nExample: Neither the teacher nor the students were present.", "concept")

    # Grade 10 English
    add(10, "english", 1, "Distinguish Defining from Non-defining Relative Clauses.", "Defining: Essential to identify the noun; no commas; can use 'that'. (e.g., 'The student who scored 100 received an award'). Non-defining: Gives extra non-essential info; separated by commas; cannot use 'that' (must use 'which/who').", "definition")
    add(10, "english", 2, "Which modal verbs express strong obligation vs advice?", "Strong Obligation: 'Must' (internal obligation/rule) and 'Have to' (external law/regulation).\nAdvice: 'Should' and 'Ought to'.", "concept")
    add(10, "english", 3, "What is the difference between a Gerund and a Present Participle?", "Both end in -ing. A Gerund functions as a noun (e.g., 'Swimming is great exercise'). A Present Participle functions as a verb tense component or an adjective (e.g., 'She is swimming', 'a crying baby').", "definition")
    add(10, "english", 4, "Name 5 verbs followed exclusively by Gerunds (-ing).", "1. Enjoy, 2. Avoid, 3. Postpone, 4. Admit, 5. Consider.\nExample: 'He avoids eating junk food'.", "concept")
    add(10, "english", 4, "Name 5 verbs followed exclusively by Infinitives (to + verb).", "1. Decide, 2. Hope, 3. Promise, 4. Refuse, 5. Manage.\nExample: 'They decided to leave early'.", "concept")

    # Grade 11 & 12 English
    add(11, "english", 1, "What is an Inversion after negative adverbials?", "When a sentence begins with a negative or restrictive adverbial (Never, Seldom, Rarely, Hardly, Scarcely, No sooner), the auxiliary verb comes before the subject.\nExample: 'Never have I seen such dedication'.", "concept")
    add(11, "english", 2, "Explain the difference between 'used to + verb' and 'be used to + -ing'.", "'Used to + base verb': Past habits/states that no longer happen (e.g., 'I used to live in Gondar').\n'Be used to + -ing/noun': Accustomed to something (e.g., 'She is used to waking up early').", "definition")
    add(12, "english", 1, "What are Cleft Sentences and why are they used?", "Sentences split into two clauses to emphasize a specific part: 'It was... that...' or 'What... is/was...'.\nExample: 'It was Menelik II who led the forces at Adwa'.", "concept")
    add(12, "english", 2, "Define the Subjunctive Mood in English with an example.", "Used to express wishes, recommendations, demands, or conditions contrary to fact. Uses base form of verb regardless of subject.\nExample: 'The doctor recommended that he take (not takes) a rest'.", "definition")
    add(12, "english", 3, "Explain the meanings of phrasal verbs: 'carry out', 'put up with', 'call off', 'bring about'.", "• Carry out: Execute or perform (a task/research)\n• Put up with: Tolerate or endure\n• Call off: Cancel an event\n• Bring about: Cause something to happen.", "definition")

    # =========================================================================
    # ⚖️ CITIZENSHIP & ETHICAL EDUCATION (GRADES 9-12)
    # =========================================================================
    # Grade 9 Citizenship
    add(9, "citizenship", 1, "Define Democracy and its core principles.", "Democracy (government of the people, by the people, for the people): Popular sovereignty, citizen participation, majority rule with protection of minority rights, periodic free and fair elections, and rule of law.", "definition")
    add(9, "citizenship", 1, "What is the Rule of Law?", "The principle that all people, institutions, and leaders are accountable to laws that are publicly promulgated, equally enforced, and independently adjudicated.", "concept")
    add(9, "citizenship", 2, "What are the three branches of democratic government and their functions?", "1. Legislative: Enacts and passes laws (Parliament / HoPR).\n2. Executive: Enforces and implements laws (Prime Minister and Cabinet).\n3. Judiciary: Interprets laws and administers justice (Courts).", "definition")
    add(9, "citizenship", 3, "What are the primary Civic Rights vs Civic Duties of an Ethiopian citizen?", "Rights: Right to life, liberty, freedom of speech, voting, equality. Duties: Paying taxes, obeying the law, defending the country, protecting public property and environment.", "concept")

    # Grade 10 Citizenship
    add(10, "citizenship", 1, "What is the Universal Declaration of Human Rights (UDHR) and when was it adopted?", "A landmark international document outlining fundamental human rights to be universally protected; adopted by the United Nations General Assembly on December 10, 1948.", "date_fact")
    add(10, "citizenship", 2, "What are the three generations of Human Rights?", "1. First Generation: Civil and political liberty rights (free speech, fair trial).\n2. Second Generation: Socio-economic rights (education, work, healthcare).\n3. Third Generation: Collective / solidarity rights (peace, healthy environment, development).", "definition")
    add(10, "citizenship", 3, "What is Corruption and what are its harmful societal effects?", "The abuse of entrusted power for private gain (bribery, embezzlement, nepotism). It undermines the rule of law, misallocates public resources, discourages investment, and deepens poverty.", "concept")

    # Grade 11 Citizenship
    add(11, "citizenship", 1, "When was the Constitution of the Federal Democratic Republic of Ethiopia (FDRE) adopted?", "Adopted on December 8, 1994, and entered into full legal force on August 21, 1995.", "date_fact")
    add(11, "citizenship", 1, "What are the roles of the House of Peoples' Representatives (HoPR) and House of Federation (HoF)?", "HoPR: Highest legislative authority, representing the whole Ethiopian population (up to 550 members). HoF: Represents Nations, Nationalities, and Peoples; interprets the Federal Constitution.", "concept")
    add(11, "citizenship", 2, "What does Article 39 of the 1995 Ethiopian Constitution guarantee?", "The unconditional right of every Nation, Nationality, and People in Ethiopia to self-determination, including the right to develop their language, culture, and self-administration up to secession.", "concept")
    add(11, "citizenship", 3, "What is Secularism according to Article 11 of the FDRE Constitution?", "Separation of State and Religion: State shall not interfere in religious matters and religion shall not interfere in state affairs. There is no state religion.", "concept")

    # Grade 12 Citizenship
    add(12, "citizenship", 1, "What is Federalism and how does it balance power?", "A system of government where sovereignty is constitutionally shared between a central national authority and regional constituent political units (Regions/States).", "definition")
    add(12, "citizenship", 2, "What are Peaceful Conflict Resolution mechanisms?", "1. Negotiation (direct discussion between parties)\n2. Mediation (assisted by a neutral third party)\n3. Arbitration (binding decision by third party)\n4. Traditional customary institutions (e.g., Shimagelena, Jaarsummaa).", "concept")
    add(12, "citizenship", 3, "Distinguish Utilitarianism from Deontological Ethics.", "Utilitarianism (Bentham, Mill): An action is morally right if it produces the greatest happiness/good for the greatest number. Deontology (Kant): Actions are morally right based on duty and moral rules (categorical imperative), regardless of consequences.", "definition")

    # =========================================================================
    # 💻 INFORMATION TECHNOLOGY (IT) (GRADES 9-12)
    # =========================================================================
    # Grade 9 IT
    add(9, "it", 1, "What is the Von Neumann Computer Architecture?", "A computer architecture consisting of a Central Processing Unit (ALU + Control Unit + Registers), Memory Unit (RAM/ROM), Input/Output mechanisms, and a shared system bus.", "concept")
    add(9, "it", 1, "What is the difference between Primary Memory (RAM) and Secondary Memory (ROM/Storage)?", "RAM (Random Access Memory): Volatile, temporary working memory read/written directly by CPU. ROM (Read-Only Memory): Non-volatile, retains BIOS firmware permanently. Storage (SSD/HDD): High-capacity persistent data storage.", "definition")
    add(9, "it", 2, "What are the three main types of System Software?", "1. Operating System (OS: Windows, Linux, Android)\n2. Device Drivers (interface between OS and hardware)\n3. Utility Programs (antivirus, disk defragmenter, file compression).", "definition")
    add(9, "it", 3, "What are Network Topologies and the most common types?", "The geometric arrangement of devices in a network:\n1. Star (devices connect to central switch/hub - most common)\n2. Bus (single backbone cable with terminators)\n3. Ring (circular token passing)\n4. Mesh (redundant point-to-point links).", "concept")

    # Grade 10 IT
    add(10, "it", 1, "What are the 7 layers of the OSI Reference Model?", "1. Physical, 2. Data Link, 3. Network, 4. Transport, 5. Session, 6. Presentation, 7. Application. ('Please Do Not Throw Sausage Pizza Away').", "definition")
    add(10, "it", 1, "Distinguish TCP from UDP protocols.", "TCP (Transmission Control Protocol): Connection-oriented, reliable, guarantees packet delivery and ordering (e.g., HTTP, email). UDP (User Datagram Protocol): Connectionless, fast, no acknowledgment (e.g., video streaming, DNS).", "concept")
    add(10, "it", 2, "What is the function of the Domain Name System (DNS)?", "Resolves human-readable domain names (e.g., www.moe.gov.et) into machine-readable numerical IP addresses (e.g., 196.188.10.5).", "definition")
    add(10, "it", 3, "What is a Relational Database Management System (RDBMS) and Primary Key?", "RDBMS: Stores structured data in related 2D tables of rows (records) and columns (attributes). Primary Key: A unique, non-null field that uniquely identifies each record in a table.", "definition")
    add(10, "it", 3, "What is the purpose of a Foreign Key in a database?", "A field in one table that uniquely identifies a row in another table, establishing a relationship and enforcing referential integrity.", "concept")

    # Grade 11 IT
    add(11, "it", 1, "What are the core SQL commands: DDL vs DML?", "DDL (Data Definition Language): CREATE, ALTER, DROP (defines table schema).\nDML (Data Manipulation Language): SELECT, INSERT, UPDATE, DELETE (manages records).", "definition")
    add(11, "it", 2, "What is an Algorithm and its 5 fundamental characteristics?", "A step-by-step finite set of instructions to solve a problem.\n1. Finiteness, 2. Definiteness, 3. Input, 4. Output, 5. Effectiveness.", "definition")
    add(11, "it", 2, "What is the time complexity (Big-O) of Linear Search vs Binary Search?", "Linear Search: O(n) (checks elements sequentially).\nBinary Search: O(log n) (requires sorted array, halves search space each iteration).", "formula")
    add(11, "it", 3, "Distinguish Stack (LIFO) from Queue (FIFO) data structures.", "Stack: Last-In, First-Out (push to add, pop to remove, e.g., browser back button, function call stack). Queue: First-In, First-Out (enqueue to add, dequeue to remove, e.g., print job queue).", "definition")

    # Grade 12 IT
    add(12, "it", 1, "What is the CIA Triad in Information Security?", "1. Confidentiality: Preventing unauthorized access to data (encryption, access control).\n2. Integrity: Ensuring data is accurate and untampered (checksums, hashing).\n3. Availability: Ensuring authorized users have timely access (redundancy, DDoS protection).", "concept")
    add(12, "it", 2, "Distinguish Symmetric from Asymmetric Encryption.", "Symmetric (AES, DES): Uses the same secret key for both encryption and decryption; faster. Asymmetric (RSA, ECC): Uses a mathematically linked key pair: Public key (encrypts) and Private key (decrypts).", "definition")
    add(12, "it", 3, "What is a Firewall and its function?", "A network security device or software that monitors and filters incoming and outgoing network traffic based on predetermined security rules.", "definition")
    add(12, "it", 4, "What is Cloud Computing and its three service models?", "On-demand delivery of computing services over the internet.\n1. IaaS (Infrastructure as a Service: VMs, AWS EC2)\n2. PaaS (Platform as a Service: Heroku, Google App Engine)\n3. SaaS (Software as a Service: Google Docs, Microsoft 365).", "definition")

    print("Language & Humanities generated successfully.")
